class Solution:
    def trap(self, height: list[int]) -> int:
        if not height:
            return 0
        left, right = 0, len(height) - 1
        left_max, right_max = height[left], height[right]
        water = 0
        while left < right:
            if left_max < right_max:
                left += 1
                left_max = max(left_max, height[left])
                water += left_max - height[left]
            else:
                right -= 1
                right_max = max(right_max, height[right])
                water += right_max - height[right]
        return water

class Solution:
    def trap(self, height: list[int]) -> int:
        n = len(height)
        if n == 0:
            return 0
        l_max = [0] * n
        r_max = [0] * n
        l_max[0] = height[0]
        for i in range(1, n):
            l_max[i] = max(l_max[i - 1], height[i])
        r_max[n - 1] = height[n - 1]
        for i in range(n - 2, -1, -1):
            r_max[i] = max(r_max[i + 1], height[i])
        total = 0
        for i in range(n):
            total += min(l_max[i], r_max[i]) - height[i]
        return total

class Solution:
    def maxPathSum(self, root: Optional[TreeNode]) -> int:
        def get_branch_max(node):
            if not node:
                return 0
            return node.val + max(0, max(get_branch_max(node.left), get_branch_max(node.right)))

        def traverse(node):
            if not node:
                return float('-inf')
            cur = node.val + max(0, get_branch_max(node.left)) + max(0, get_branch_max(node.right))
            return max(cur, traverse(node.left), traverse(node.right))

        return traverse(root)

class Solution:
    def longestIncreasingPath(self, matrix: list[list[int]]) -> int:
        if not matrix or not matrix[0]:
            return 0
        m, n = len(matrix), len(matrix[0])
        memo = {}

        def dfs(r: int, c: int) -> int:
            if (r, c) in memo:
                return memo[(r, c)]
            val = matrix[r][c]
            res = 1
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] > val:
                    res = max(res, 1 + dfs(nr, nc))
            memo[(r, c)] = res
            return res

        return max(dfs(r, c) for r in range(m) for c in range(n))
